INSERT INTO `ai_code_rule` (`id`, `tenant_id`, `rule_code`, `rule_name`, `scene`, `template`, `reset_policy`, `seq_length`, `status`, `builtin`, `remark`, `options`, `create_by`, `create_time`, `create_dept`, `update_by`, `update_time`) VALUES (1910000000000008601,1,'material_code','物料编码','COMMON','WL${yyyyMMddHHmmss}${seq:3}','SECOND',3,1,1,'适合物料编码：WL + 年月日时分秒 + 3位同秒流水',NULL,1,'2026-07-02 16:13:52',1,1,'2026-07-02 16:13:52'),(1910000000000008602,1,'document_daily_no','通用单据日流水','COMMON','DOC${yyyyMMdd}${seq:4}','DAY',4,1,1,'适合普通业务单据：DOC + 年月日 + 4位日流水',NULL,1,'2026-07-02 16:13:52',1,1,'2026-07-02 16:13:52'),(1910000000000008603,1,'order_no','订单编号','COMMON','ORD${yyyyMMdd}${seq:5}','DAY',5,1,1,'适合订单类单据：ORD + 年月日 + 5位日流水',NULL,1,'2026-07-02 16:13:52',1,1,'2026-07-02 16:13:52'),(1910000000000008604,1,'contract_no','合同编号','COMMON','HT${yyyyMM}${seq:5}','MONTH',5,1,1,'适合合同类单据：HT + 年月 + 5位月流水',NULL,1,'2026-07-02 16:13:52',1,1,'2026-07-02 16:13:52'),(1910000000000008605,1,'customer_code','客户编码','COMMON','C${seq:6}','NONE',6,1,1,'适合主数据编码：C + 6位全局流水',NULL,1,'2026-07-02 16:13:52',1,1,'2026-07-02 16:13:52'),(1910000000000008606,1,'org_daily_no','组织日流水','COMMON','${orgCode}${yyyyMMdd}${seq:4}','DAY',4,1,1,'适合按组织隔离的日流水：组织编码 + 年月日 + 4位流水',NULL,1,'2026-07-02 16:13:52',1,1,'2026-07-02 16:13:52'),(1910000000000009301,1,'supplier_code','供应商编号','PROCUREMENT_WAREHOUSE','SUP${seq:5}','NONE',5,1,1,'供应商主数据编号',NULL,1,'2026-07-03 16:30:06',1,1,'2026-07-03 16:30:06'),(1910000000000009302,1,'warehouse_code','仓库编号','PROCUREMENT_WAREHOUSE','WH${seq:4}','NONE',4,1,1,'仓库主数据编号',NULL,1,'2026-07-03 16:30:06',1,1,'2026-07-03 16:30:06'),(1910000000000009303,1,'purchase_no','采购单号','PROCUREMENT_WAREHOUSE','CG${yyyyMMdd}${seq:4}','DAY',4,1,1,'采购单日流水',NULL,1,'2026-07-03 16:30:06',1,1,'2026-07-03 16:30:06'),(1910000000000009304,1,'outbound_no','出库单号','PROCUREMENT_WAREHOUSE','CK${yyyyMMdd}${seq:4}','DAY',4,1,1,'出库单日流水',NULL,1,'2026-07-03 16:30:06',1,1,'2026-07-03 16:30:06'),(1910000000000009305,1,'transfer_no','调拨单号','PROCUREMENT_WAREHOUSE','DB${yyyyMMdd}${seq:4}','DAY',4,1,1,'调拨单日流水',NULL,1,'2026-07-03 16:30:06',1,1,'2026-07-03 16:30:06');
